/* Câu hỏi chờ duyệt (BỔ SUNG): chương chuan-do-axit-bazo (Chuẩn độ acid – base)
   Dạng mới: D03 base yếu + acid mạnh; D04 bước nhảy/chỉ thị; D05 đa acid & hỗn hợp;
   D06 định lượng mẫu thật; D07 Kjeldahl & chuẩn độ ngược; D08 câu chùm quy trình chuẩn độ. */
NGAN_HANG.push(
  { id: "CD-B001", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 3, de: "Một dung dịch CH<sub>3</sub>NH<sub>2</sub> có nồng độ 0,0400 M (pK<sub>b</sub> = 3,355). Vì C/K<sub>b</sub> = 90,6 &lt; 400 nên phải giải đúng phương trình bậc hai (không dùng gần đúng). Tính pH của dung dịch.", phuongAn: ["7,98", "11,62", "2,40", "11,60"], dapAn: "D", loiGiai: "Đặt x = [OH<sup>−</sup>], giải \\( x^2 + K_bx - K_bC = 0 \\) với \\( K_b = 10^{-3,355} = 4,42\\cdot10^{-4} \\), C = 0,0400 M: x = 3,99·10<sup>−3</sup> M → pOH = 2,40 → pH = 11,60. Lỗi hay gặp: «11,62» (dùng gần đúng x = √(K<sub>b</sub>C) thay vì giải đúng phương trình bậc hai, dù C/K<sub>b</sub> chỉ bằng 90,6 &lt; 400 nên gần đúng không hợp lệ); «7,98» (nhầm lấy pK<sub>a</sub> của acid liên hợp CH<sub>3</sub>NH<sub>3</sub><sup>+</sup> là 10,645 để dùng làm pK<sub>b</sub> của CH<sub>3</sub>NH<sub>2</sub>); «2,40» (tính đúng pOH = 2,40 nhưng quên đổi sang pH = 14 − pOH, báo luôn pOH là pH)." },
  { id: "CD-B002", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 3, de: "Chuẩn độ 20,00 mL CH<sub>3</sub>NH<sub>2</sub> 0,1000 M bằng HCl 0,2000 M. Khi đã thêm 7,00 mL HCl, tính pH của dung dịch (pK<sub>b</sub> CH<sub>3</sub>NH<sub>2</sub> = 3,355).", phuongAn: ["10,28", "2,99", "11,01", "11,07"], dapAn: "A", loiGiai: "Số mmol ban đầu CH<sub>3</sub>NH<sub>2</sub> = 2,000; đã phản ứng = 0,2000·7,00 = 1,400 mmol → còn lại CH<sub>3</sub>NH<sub>2</sub> 0,600 mmol, tạo CH<sub>3</sub>NH<sub>3</sub><sup>+</sup> 1,400 mmol. Đây là hệ đệm base/acid liên hợp, dùng \\( \\text{pH} = \\text{p}K_a + \\lg\\dfrac{[\\text{B}]}{[\\text{BH}^+]} \\) với pK<sub>a</sub>(CH<sub>3</sub>NH<sub>3</sub><sup>+</sup>) = 14 − 3,355 = 10,645: pH = 10,645 + lg(0,600/1,400) = 10,28. Lỗi hay gặp: «11,01» (đảo ngược tỉ số, lấy lg([BH<sup>+</sup>]/[B]) thay vì lg([B]/[BH<sup>+</sup>])); «2,99» (quên đổi pK<sub>b</sub> sang pK<sub>a</sub> của acid liên hợp, dùng thẳng 3,355 thay cho 10,645); «11,07» (quên lấy logarit của tỉ số nồng độ, cộng thẳng tỉ số [B]/[BH<sup>+</sup>] = 0,4286 vào pK<sub>a</sub> thay vì cộng lg của tỉ số đó)." },
  { id: "CD-B003", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 3, de: "Chuẩn độ 20,00 mL CH<sub>3</sub>NH<sub>2</sub> 0,1000 M bằng HCl 0,2000 M đến đúng thể tích tương đương. Tính pH của dung dịch tại điểm tương đương.", phuongAn: ["11,82", "5,82", "5,91", "2,27"], dapAn: "C", loiGiai: "V<sub>tđ</sub> = 0,1000·20,00/0,2000 = 10,00 mL. Tại tương đương, toàn bộ CH<sub>3</sub>NH<sub>2</sub> chuyển thành CH<sub>3</sub>NH<sub>3</sub><sup>+</sup>, nồng độ C = 2,000 mmol/30,00 mL = 0,06667 M; \\( K_a = 10^{-10,645} \\) (rất nhỏ so với C nên dùng gần đúng \\( [\\text{H}^+] = \\sqrt{K_aC} \\)), tức pH = ½(pK<sub>a</sub> − lgC): [H<sup>+</sup>] = 1,23·10<sup>−6</sup> M → pH = 5,91. Lỗi hay gặp: «5,82» (quên cộng thể tích HCl vào mẫu số, dùng nhầm C = 0,1000 M ban đầu thay vì nồng độ đã pha loãng 0,06667 M); «11,82» (quên hệ số ½ trong công thức gần đúng, tính pH = pK<sub>a</sub> − lgC thay vì ½(pK<sub>a</sub> − lgC)); «2,27» (nhầm hằng số, dùng K<sub>b</sub>(CH<sub>3</sub>NH<sub>2</sub>) = 10<sup>−3,355</sup> thay vì K<sub>a</sub> của acid liên hợp CH<sub>3</sub>NH<sub>3</sub><sup>+</sup>)." },
  { id: "CD-B004", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 4, de: "Một dung dịch CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> có nồng độ 0,0150 M (pK<sub>b</sub> = 3,364). Vì C/K<sub>b</sub> = 34,7 &lt; 400 nên phải giải đúng phương trình bậc hai. Tính pH của dung dịch.", phuongAn: ["11,37", "2,63", "11,41", "7,77"], dapAn: "A", loiGiai: "Đặt x = [OH<sup>−</sup>], giải \\( x^2 + K_bx - K_bC = 0 \\) với K<sub>b</sub> = 10<sup>−3,364</sup> = 4,33·10<sup>−4</sup>, C = 0,0150 M: x = 3,45·10<sup>−3</sup> M → pOH = 2,46 → pH = 11,37. Lỗi hay gặp: «11,41» (dùng gần đúng x = √(K<sub>b</sub>C) dù C/K<sub>b</sub> chỉ 34,7, sai số đủ lớn để lệch kết quả); «7,77» (nhầm lấy pK<sub>a</sub> của acid liên hợp CH<sub>3</sub>CH<sub>2</sub>NH<sub>3</sub><sup>+</sup> (10,636) làm pK<sub>b</sub> của CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub>); «2,63» (tính đúng pOH = 2,63 nhưng báo luôn là pH, quên đổi pH = 14 − pOH)." },
  { id: "CD-B005", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 3, de: "Chuẩn độ 25,00 mL CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> 0,1200 M bằng HCl 0,1500 M. Khi đã thêm 13,00 mL HCl, tính pH của dung dịch (pK<sub>b</sub> CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> = 3,364).", phuongAn: ["11,17", "3,10", "10,37", "10,90"], dapAn: "C", loiGiai: "mmol CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> ban đầu = 3,000; đã phản ứng = 0,1500·13,00 = 1,950 mmol → còn lại CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> 1,050 mmol, tạo CH<sub>3</sub>CH<sub>2</sub>NH<sub>3</sub><sup>+</sup> 1,950 mmol. pK<sub>a</sub>(CH<sub>3</sub>CH<sub>2</sub>NH<sub>3</sub><sup>+</sup>) = 14 − 3,364 = 10,636; pH = 10,636 + lg(1,050/1,950) = 10,37. Lỗi hay gặp: «10,90» (đảo ngược tỉ số trong công thức Henderson–Hasselbalch, lấy lg([BH<sup>+</sup>]/[B]) thay vì lg([B]/[BH<sup>+</sup>])); «3,10» (quên đổi pK<sub>b</sub> sang pK<sub>a</sub> của acid liên hợp, dùng thẳng 3,364); «11,17» (quên lấy logarit của tỉ số nồng độ, cộng thẳng tỉ số [B]/[BH<sup>+</sup>] = 0,5385 vào pK<sub>a</sub> thay vì cộng lg của tỉ số đó)." },
  { id: "CD-B006", chuong: "chuan-do-axit-bazo", dang: "D03 · Chuẩn độ base yếu bằng acid mạnh", dangMoi: true, mucDo: 2, de: "Chuẩn độ 25,00 mL CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> 0,1200 M bằng HCl 0,1500 M. Thể tích tương đương là 20,00 mL. Tính pH của dung dịch khi đã thêm 25,00 mL HCl.", phuongAn: ["1,52", "1,12", "1,82", "5,91"], dapAn: "C", loiGiai: "HCl dùng dư so với tương đương: n(HCl) = 0,1500·25,00 = 3,750 mmol; n(CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub>) ban đầu = 0,1200·25,00 = 3,000 mmol. H<sup>+</sup> dư = (3,750 − 3,000)/(25,00 + 25,00) = 0,0150 M → pH = −lg(0,0150) = 1,82. Lỗi hay gặp: «1,52» (dùng nhầm thể tích HCl thêm vào (25,00 mL) làm mẫu số thay vì tổng thể tích dung dịch 50,00 mL); «1,12» (quên trừ đi lượng CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> ban đầu đã bị trung hòa, tính H<sup>+</sup> dư = n(HCl)/V<sub>tổng</sub>); «5,91» (tưởng vẫn đang ở điểm tương đương, quên đã cho dư HCl, tính pH của CH<sub>3</sub>CH<sub>2</sub>NH<sub>3</sub><sup>+</sup> tại V<sub>tđ</sub> = 20,00 mL thay vì V = 25,00 mL)." },
  { id: "CD-B007", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 1, de: "Chỉ số chuẩn độ pT là giá trị pH mà mắt người quan sát thấy chỉ thị đổi màu rõ nhất. Trong các pT thường dùng (metyl da cam 4; metyl đỏ 5; bromthymol xanh 7; phenolphtalein 9), chỉ thị có pT = 5 là", phuongAn: ["Metyl da cam", "Phenolphtalein", "Bromthymol xanh", "Metyl đỏ"], dapAn: "D", loiGiai: "Theo bảng tra pT thường dùng: metyl da cam 4; metyl đỏ 5; bromthymol xanh 7; phenolphtalein 9 → pT = 5 ứng với metyl đỏ. Lỗi hay gặp: «Metyl da cam» (nhớ nhầm sang pT = 4); «Bromthymol xanh» (nhớ nhầm sang pT = 7); «Phenolphtalein» (nhớ nhầm sang pT = 9)." },
  { id: "CD-B008", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 1, de: "Chỉ thị bromocresol lục (bromcresol lục) có khoảng đổi màu và chiều đổi màu (khi pH tăng dần) đúng theo bảng tra là", phuongAn: ["3,8 – 5,4; vàng → xanh lam", "4,4 – 6,2; đỏ → vàng", "3,8 – 5,4; xanh lam → vàng", "7,2 – 8,8; vàng → đỏ"], dapAn: "A", loiGiai: "Theo bảng tra chỉ thị acid–base, bromocresol lục đổi màu trong khoảng pH 3,8 – 5,4, từ vàng (dạng acid, pH thấp) sang xanh lam (dạng base, pH cao) khi pH tăng dần. Lỗi hay gặp: «xanh lam → vàng» (đảo ngược chiều đổi màu so với chiều pH tăng); «7,2 – 8,8; vàng → đỏ» (nhầm sang khoảng và màu của cresol đỏ); «4,4 – 6,2; đỏ → vàng» (nhầm sang khoảng và màu của metyl đỏ)." },
  { id: "CD-B009", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 2, de: "Chuẩn độ 50,00 mL dung dịch HCl 0,1000 M bằng NaOH 0,1000 M. Tính bước nhảy chuẩn độ, tức hiệu số pH giữa hai thời điểm 100,1% và 99,9% thể tích tương đương.", phuongAn: ["7,40", "5,40", "2,70", "6,00"], dapAn: "B", loiGiai: "V<sub>tđ</sub> = 50,00 mL. Ở 99,9%V<sub>tđ</sub> (49,95 mL), H<sup>+</sup> dư = (5,000 − 4,995)/(50,00+49,95) mmol/mL = 5,00·10<sup>−5</sup> M → pH = 4,30. Ở 100,1%V<sub>tđ</sub> (50,05 mL), OH<sup>−</sup> dư tương tự = 5,00·10<sup>−5</sup> M → pOH = 4,30 → pH = 9,70. Bước nhảy = 9,70 − 4,30 = 5,40. Lỗi hay gặp: «6,00» (quên cộng thể tích NaOH đã thêm vào mẫu số, dùng cố định V = 50,00 mL cho cả hai nhánh); «7,40» (nhầm dùng khoảng ±1% thay vì ±0,1% như đề yêu cầu); «2,70» (quên rằng bước nhảy trải đều hai phía quanh pH trung hòa 7, chỉ tính độ lệch một phía (9,70 − 7,00) rồi coi đó là cả bước nhảy)." },
  { id: "CD-B010", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 3, de: "Chuẩn độ dung dịch HCl bằng NaOH có cùng nồng độ C (thể tích ban đầu bằng thể tích tương đương). Tính nồng độ C tối thiểu để bước nhảy chuẩn độ (giữa 99,9% và 100,1% thể tích tương đương) đạt đúng 3 đơn vị pH.", phuongAn: ["3,16·10<sup>−3</sup> M", "2,00·10<sup>−2</sup> M", "2,00·10<sup>−3</sup> M", "6,32·10<sup>−3</sup> M"], dapAn: "D", loiGiai: "Với hai nồng độ đầu bằng nhau, thể tích gần như gấp đôi ở mỗi nhánh nên bước nhảy \\( \\Delta\\text{pH} = 14 + 2\\lg(C\\cdot5\\cdot10^{-4}) \\). Giải \\( \\lg(C\\cdot5\\cdot10^{-4}) = (3-14)/2 = -5,5 \\) → C = 10<sup>−5,5</sup>/(5·10<sup>−4</sup>) = 6,32·10<sup>−3</sup> M. Lỗi hay gặp: «3,16·10<sup>−3</sup> M» (quên rằng thể tích dung dịch gần như gấp đôi, dùng nhầm hệ số 10<sup>−3</sup> thay vì 5·10<sup>−4</sup> trong biểu thức nồng độ dư); «2,00·10<sup>−2</sup> M» (đọc nhầm yêu cầu đề là bước nhảy 4 đơn vị pH thay vì 3 đơn vị); «2,00·10<sup>−3</sup> M» (đọc nhầm yêu cầu đề là bước nhảy 2 đơn vị pH thay vì 3 đơn vị)." },
  { id: "CD-B011", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 3, de: "Chuẩn độ 50,00 mL dung dịch acid propionic 0,1000 M (pK<sub>a</sub> = 4,874) bằng NaOH 0,1000 M. Tính bước nhảy chuẩn độ, tức hiệu số pH giữa 100,1% và 99,9% thể tích tương đương.", phuongAn: ["5,40", "1,83", "7,82", "0,91"], dapAn: "B", loiGiai: "V<sub>tđ</sub> = 50,00 mL. Ở 99,9%V<sub>tđ</sub>, tỉ lệ [A<sup>−</sup>]/[HA] = 999 → pH = 4,874 + lg(999) = 7,87 (đệm Henderson–Hasselbalch). Ở 100,1%V<sub>tđ</sub>, NaOH dư = 5,00·10<sup>−5</sup> M → pOH = 4,30 → pH = 9,70. Bước nhảy = 9,70 − 7,87 = 1,83. Lỗi hay gặp: «5,40» (coi acid propionic như acid mạnh, bỏ qua K<sub>a</sub> khi tính pH ở nhánh trước tương đương); «7,82» (đổi dấu công thức Henderson–Hasselbalch, tính pH = pK<sub>a</sub> − lg(999) thay vì pK<sub>a</sub> + lg(999)); «0,91» (chỉ tính từ đúng điểm tương đương (pH = 8,79) đến 100,1%, quên rằng bước nhảy phải tính từ 99,9% đến 100,1%)." },
  { id: "CD-B012", chuong: "chuan-do-axit-bazo", dang: "D04 · Bước nhảy, chọn chỉ thị, sai số chỉ thị", dangMoi: true, mucDo: 4, de: "Chuẩn độ 40,00 mL dung dịch CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> 0,1000 M (pK<sub>b</sub> = 3,364) bằng HCl 0,1000 M. Trong 4 lựa chọn dưới đây (đã kèm mô tả chiều đổi màu quan sát được trong phép chuẩn độ này), lựa chọn phù hợp nhất là", phuongAn: ["Metyl đỏ; đỏ → vàng", "Phenolphtalein; đổi màu không màu → hồng", "Metyl đỏ; đổi màu vàng → đỏ khi pH giảm qua khoảng 4,4 – 6,2", "Bromcresol lục; đổi màu xanh lam → vàng khi pH giảm qua khoảng 3,8 – 5,4"], dapAn: "C", loiGiai: "V<sub>tđ</sub> = 40,00 mL. Bước nhảy: ở 99,9%V<sub>tđ</sub>, pH = (14−3,364) − lg(999) = 7,64; ở 100,1%V<sub>tđ</sub>, HCl dư 5,00·10<sup>−5</sup> M → pH = 4,30. pH tại tương đương: [CH<sub>3</sub>CH<sub>2</sub>NH<sub>3</sub><sup>+</sup>] = 0,05000 M, K<sub>a</sub> = 10<sup>−10,636</sup> → [H<sup>+</sup>] = √(K<sub>a</sub>C) → pH = 5,97, nằm gọn trong khoảng metyl đỏ (4,4 – 6,2). Vì đây là base yếu bị chuẩn độ bằng acid mạnh, pH giảm dần suốt phép chuẩn độ nên chỉ thị đổi màu theo chiều ngược với chiều ghi trong bảng (bảng quy ước theo pH tăng): từ vàng (dạng base, pH cao) sang đỏ (dạng acid, pH thấp). Lỗi hay gặp: «đỏ → vàng» (giữ nguyên chiều đổi màu ghi trong bảng ứng với pH tăng dần, quên rằng ở phép chuẩn độ này pH đang giảm dần nên phải đảo chiều); «Phenolphtalein» (khoảng đổi màu 8,2 – 10,0 nằm ngoài hẳn bước nhảy 4,30 – 7,64 của phép chuẩn độ base yếu này); «Bromcresol lục» (khoảng 3,8 – 5,4 không chứa trọn pH tương đương 5,97, kém an toàn hơn metyl đỏ)." },
  { id: "CD-B013", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 2, de: "20,00 mL nước chanh chứa acid citric (C<sub>3</sub>H<sub>4</sub>(OH)(COOH)<sub>3</sub>, ba nấc pK<sub>a</sub> 3,128 ; 4,761 ; 6,396) được chuẩn độ bằng NaOH 0,1050 M với chỉ thị phenolphtalein, hết 9,60 mL (phản ứng theo tỉ lệ 1 acid citric : 3 NaOH). Tính nồng độ acid citric trong nước chanh.", phuongAn: ["0,0252 M", "0,0168 M", "0,0504 M", "0,1512 M"], dapAn: "B", loiGiai: "n(NaOH) = 0,1050·9,60 = 1,008 mmol; vì tỉ lệ 1 acid citric : 3 NaOH nên n(acid citric) = 1,008/3 = 0,336 mmol trong 20,00 mL → C = 0,336/20,00 = 0,0168 M. Lỗi hay gặp: «0,0504 M» (quên hệ số 3, coi phản ứng theo tỉ lệ 1 : 1); «0,0252 M» (chia nhầm cho 2, tưởng acid citric chỉ có hai nhóm –COOH phản ứng); «0,1512 M» (nhân với 3 thay vì chia, đảo ngược chiều hệ số tỉ lượng)." },
  { id: "CD-B014", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 2, de: "Nếu dùng metyl da cam (đổi màu ở pH 3,1 – 4,4) thay vì phenolphtalein để chuẩn độ acid citric (C<sub>3</sub>H<sub>4</sub>(OH)(COOH)<sub>3</sub>, pK<sub>a1,2,3</sub> = 3,128 ; 4,761 ; 6,396) bằng NaOH, phép chuẩn độ sẽ dừng lại gần đúng ở nấc nào?", phuongAn: ["Chưa trung hòa proton nào (còn nguyên C<sub>3</sub>H<sub>4</sub>(OH)(COOH)<sub>3</sub>)", "Nấc 2, đã trung hòa 2 proton (tạo HCit<sup>2−</sup>)", "Nấc 3, đã trung hòa cả 3 proton (tạo Cit<sup>3−</sup>)", "Nấc 1, mới trung hòa 1 proton (tạo H<sub>2</sub>Cit<sup>−</sup>)"], dapAn: "D", loiGiai: "Khoảng đổi màu của metyl da cam (3,1 – 4,4) nằm sát ngay pK<sub>a1</sub> = 3,128: khi NaOH vừa đủ trung hòa proton thứ nhất (tạo H<sub>2</sub>Cit<sup>−</sup>) thì pH đã vượt qua khoảng đổi màu này, nên chỉ thị đổi màu ngay tại đó — phép chuẩn độ dừng gần đúng ở nấc 1. Lỗi hay gặp: chọn «Nấc 2» (nhầm sang pK<sub>a2</sub> = 4,761, cao hơn hẳn khoảng đổi màu của metyl da cam); chọn «Nấc 3» (nhầm với trường hợp dùng phenolphtalein, đổi màu ở pH cao hơn nhiều); chọn «Chưa trung hòa proton nào» (quên rằng pK<sub>a1</sub> = 3,128 đã nằm ngay trong khoảng đổi màu 3,1 – 4,4 của metyl da cam)." },
  { id: "CD-B015", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 3, de: "20,00 mL một mẫu nước chanh khác chứa acid citric được chuẩn độ bằng NaOH 0,1200 M (tỉ lệ 1 : 3) với chỉ thị phenolphtalein, hết 12,30 mL. Tính hàm lượng acid citric trong mẫu theo g/L (M = 192,124).", phuongAn: ["14,18 g/L", "4,73 g/L", "5,17 g/L", "7,09 g/L"], dapAn: "B", loiGiai: "n(NaOH) = 0,1200·12,30 = 1,476 mmol; n(acid citric) = 1,476/3 = 0,4920 mmol → C = 0,4920/20,00 = 0,0246 M → g/L = 0,0246·192,124 = 4,73 g/L. Lỗi hay gặp: «14,18 g/L» (quên hệ số 3, coi phản ứng 1 : 1); «7,09 g/L» (chia nhầm cho 2 thay vì 3); «5,17 g/L» (nhầm dùng khối lượng mol dạng acid citric ngậm một nước, M = 210,14, thay vì dạng khan M = 192,124)." },
  { id: "CD-B016", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 3, de: "Cân 0,3850 g mẫu KH<sub>2</sub>PO<sub>4</sub> kĩ thuật (M = 136,09), hòa tan hoàn toàn rồi chuẩn độ bằng NaOH 0,1005 M (phản ứng H<sub>2</sub>PO<sub>4</sub><sup>−</sup> + OH<sup>−</sup> → HPO<sub>4</sub><sup>2−</sup> + H<sub>2</sub>O, tỉ lệ 1 : 1), hết 25,20 mL. Tính % độ tinh khiết của mẫu.", phuongAn: ["64,47 %", "89,52 %", "44,76 %", "78,93 %"], dapAn: "B", loiGiai: "n(NaOH) = 0,1005·25,20 = 2,533 mmol = n(KH<sub>2</sub>PO<sub>4</sub>) (tỉ lệ 1 : 1) → khối lượng tinh khiết = 2,533·10<sup>−3</sup>·136,09 = 0,3448 g → % = 0,3448/0,3850·100 = 89,52 %. Lỗi hay gặp: «44,76 %» (nhầm tưởng KH<sub>2</sub>PO<sub>4</sub> có 2 proton phản ứng với NaOH ở đây, dùng tỉ lệ 2 : 1); «64,47 %» (nhầm dùng M = 98,00 của acid gốc H<sub>3</sub>PO<sub>4</sub> thay vì M = 136,09 của muối KH<sub>2</sub>PO<sub>4</sub>); «78,93 %» (nhầm dùng M = 119,98 của muối natri dihydrophotphat NaH<sub>2</sub>PO<sub>4</sub> thay vì kali dihydrophotphat KH<sub>2</sub>PO<sub>4</sub>)." },
  { id: "CD-B017", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 4, de: "Hút 25,00 mL nước ép trái cây (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước đến vạch (dung dịch B). Hút 25,00 mL dung dịch B, chuẩn độ bằng NaOH 0,1100 M (tỉ lệ 1 acid citric : 3 NaOH) với chỉ thị phenolphtalein, hết 10,80 mL. Tính hàm lượng acid citric trong nước ép ban đầu A theo g/L (M = 192,124).", phuongAn: ["0,304 g/L", "3,04 g/L", "91,30 g/L", "30,43 g/L"], dapAn: "D", loiGiai: "n(NaOH) = 0,1100·10,80 = 1,188 mmol; n(acid citric) = 1,188/3 = 0,396 mmol trong 25,00 mL B → C<sub>B</sub> = 0,01584 M. Vì B pha loãng 250,0/25,00 = 10 lần từ A: C<sub>A</sub> = 0,1584 M → g/L = 0,1584·192,124 = 30,43 g/L. Lỗi hay gặp: «3,04 g/L» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,304 g/L» (dùng ngược hệ số pha loãng 25,00/250,0 thay vì 250,0/25,00); «91,30 g/L» (quên chia cho 3 trong bước tính mol acid citric nhưng vẫn nhân đúng hệ số pha loãng)." },
  { id: "CD-B018", chuong: "chuan-do-axit-bazo", dang: "D05 · Đa acid và hỗn hợp", dangMoi: true, mucDo: 3, de: "Trộn để có dung dịch đệm phosphate chứa KH<sub>2</sub>PO<sub>4</sub> 0,12 M và K<sub>2</sub>HPO<sub>4</sub> 0,18 M (dùng pK<sub>a</sub> của H<sub>3</sub>PO<sub>4</sub>: 2,12 ; 7,21 ; 12,32). Tính pH của dung dịch đệm này.", phuongAn: ["12,50", "7,03", "7,39", "2,30"], dapAn: "C", loiGiai: "H<sub>2</sub>PO<sub>4</sub><sup>−</sup>/HPO<sub>4</sub><sup>2−</sup> là cặp đệm dùng pK<sub>a2</sub> = 7,21: pH = pK<sub>a2</sub> + lg([HPO<sub>4</sub><sup>2−</sup>]/[H<sub>2</sub>PO<sub>4</sub><sup>−</sup>]) = 7,21 + lg(0,18/0,12) = 7,21 + 0,18 = 7,39. Lỗi hay gặp: «7,03» (đảo ngược tỉ số nồng độ, lấy lg(0,12/0,18) thay vì lg(0,18/0,12)); «2,30» (nhầm dùng pK<sub>a1</sub> = 2,12 của cặp H<sub>3</sub>PO<sub>4</sub>/H<sub>2</sub>PO<sub>4</sub><sup>−</sup> thay vì pK<sub>a2</sub>); «12,50» (nhầm dùng pK<sub>a3</sub> = 12,32 của cặp HPO<sub>4</sub><sup>2−</sup>/PO<sub>4</sub><sup>3−</sup> thay vì pK<sub>a2</sub>)." },
  { id: "CD-B019", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 2, de: "Chuẩn hóa một dung dịch NaOH: hút 10,00 mL dung dịch NaOH cần chuẩn hóa, chuẩn độ bằng dung dịch kali hydrophtalat (KHP) chuẩn gốc 0,1002 M (phản ứng 1 : 1), hết 9,85 mL. Tính nồng độ chính xác của dung dịch NaOH.", phuongAn: ["0,987 M", "0,04935 M", "0,0987 M", "0,1017 M"], dapAn: "C", loiGiai: "Tại điểm tương đương n(NaOH) = n(KHP): C(NaOH)·10,00 = 0,1002·9,85 → C(NaOH) = 0,1002·9,85/10,00 = 0,0987 M. Lỗi hay gặp: «0,1017 M» (đảo ngược tỉ số thể tích, tính C(NaOH) = 0,1002·10,00/9,85); «0,04935 M» (coi KHP có 2 nhóm acid phản ứng, chia thêm cho 2); «0,987 M» (quên chia cho thể tích NaOH đem chuẩn độ, báo luôn số mmol KHP đã dùng (0,987 mmol) làm nồng độ)." },
  { id: "CD-B020", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 3, de: "Hút 25,00 mL giấm ăn (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng NaOH 0,1050 M (đã chuẩn hóa), hết 8,40 mL. Tính nồng độ CH<sub>3</sub>COOH trong giấm ăn ban đầu (dung dịch A).", phuongAn: ["0,3528 M", "0,0882 M", "0,00882 M", "0,882 M"], dapAn: "D", loiGiai: "n(NaOH) = 0,1050·8,40 = 0,882 mmol = n(CH<sub>3</sub>COOH) trong 10,00 mL B → C<sub>B</sub> = 0,0882 M. B pha loãng 250,0/25,00 = 10 lần từ A → C<sub>A</sub> = 0,882 M. Lỗi hay gặp: «0,0882 M» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,00882 M» (dùng ngược hệ số pha loãng 25,00/250,0); «0,3528 M» (đọc nhầm thể tích B đem chuẩn độ, dùng 25,00 mL thay vì 10,00 mL)." },
  { id: "CD-B021", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 3, de: "Hút 10,00 mL giấm ăn (dung dịch A, khối lượng riêng d = 1,008 g/mL) cho vào bình định mức 100,0 mL, thêm nước đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng NaOH 0,0400 M, hết 10,50 mL. Tính % khối lượng CH<sub>3</sub>COOH (M = 60,05) trong giấm ăn ban đầu.", phuongAn: ["2,50 %", "3,42 %", "0,250 %", "2,52 %"], dapAn: "A", loiGiai: "n(NaOH) = 0,0400·10,50 = 0,420 mmol = n(CH<sub>3</sub>COOH) trong 10,00 mL B → C<sub>B</sub> = 0,0420 M; B pha loãng 10 lần từ A → C<sub>A</sub> = 0,420 M. %m = C<sub>A</sub>·M/(d·1000)·100 = 0,420·60,05/(1,008·1000)·100 = 2,50 %. Lỗi hay gặp: «0,250 %» (quên hệ số pha loãng 10 lần, dùng C<sub>B</sub> thay vì C<sub>A</sub>); «2,52 %» (quên đổi khối lượng riêng, mặc định d = 1,000 g/mL); «3,42 %» (nhầm dùng khối lượng mol của muối natri acetat CH<sub>3</sub>COONa (82,03) — muối tạo thành trong phản ứng — thay vì M = 60,05 của CH<sub>3</sub>COOH)." },
  { id: "CD-B022", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 3, de: "Hút 20,00 mL nước lau kính chứa NH<sub>3</sub> (dung dịch A) cho vào bình định mức 200,0 mL, thêm nước đến vạch (dung dịch B). Hút 25,00 mL dung dịch B, chuẩn độ bằng HCl 0,1020 M với chỉ thị bromocresol lục, hết 14,60 mL. Tính nồng độ NH<sub>3</sub> trong mẫu ban đầu (dung dịch A).", phuongAn: ["0,0596 M", "5,96 M", "0,596 M", "0,00596 M"], dapAn: "C", loiGiai: "n(HCl) = 0,1020·14,60 = 1,489 mmol = n(NH<sub>3</sub>) trong 25,00 mL B → C<sub>B</sub> = 0,0596 M. B pha loãng 200,0/20,00 = 10 lần từ A → C<sub>A</sub> = 0,596 M. Lỗi hay gặp: «0,0596 M» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,00596 M» (dùng ngược hệ số pha loãng 20,00/200,0); «5,96 M» (nhân hệ số pha loãng hai lần, tưởng cả bước định mức A→B lẫn bước hút B đem chuẩn độ đều là pha loãng, trong khi bước hút B chỉ là lấy mẫu phân tích chứ không pha loãng thêm)." },
  { id: "CD-B023", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 2, de: "Hút 25,00 mL nước lau kính chứa NH<sub>3</sub> (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, chuẩn độ bằng HCl 0,0950 M với chỉ thị bromocresol lục, hết 12,35 mL. Tính hàm lượng NH<sub>3</sub> (M = 17,03) trong mẫu ban đầu A theo g/L.", phuongAn: ["0,999 g/L", "21,39 g/L", "9,99 g/L", "8,22 g/L"], dapAn: "C", loiGiai: "n(HCl) = 0,0950·12,35 = 1,173 mmol = n(NH<sub>3</sub>) trong 20,00 mL B → C<sub>B</sub> = 0,05866 M. B pha loãng 250,0/25,00 = 10 lần từ A → C<sub>A</sub> = 0,5866 M → g/L = 0,5866·17,03 = 9,99 g/L. Lỗi hay gặp: «0,999 g/L» (quên hệ số pha loãng 10 lần); «8,22 g/L» (nhầm dùng M = 14,01 của nguyên tố N thay vì M = 17,03 của phân tử NH<sub>3</sub>); «21,39 g/L» (nhầm dùng M = 36,46 của HCl thay vì M = 17,03 của NH<sub>3</sub>)." },
  { id: "CD-B024", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 3, de: "Cân 0,8500 g mẫu bột chứa acid benzoic (C<sub>6</sub>H<sub>5</sub>COOH, M = 122,12, pK<sub>a</sub> = 4,19), hòa tan hoàn toàn trong ethanol đã trung hòa, định mức thành 100,0 mL (dung dịch A). Hút 20,00 mL dung dịch A, thêm phenolphtalein, chuẩn độ bằng NaOH 0,1035 M, hết 9,40 mL. Tính % độ tinh khiết acid benzoic trong mẫu.", phuongAn: ["69,89 %", "13,98 %", "2,80 %", "82,47 %"], dapAn: "A", loiGiai: "n(NaOH) = 0,1035·9,40 = 0,9729 mmol = n(C<sub>6</sub>H<sub>5</sub>COOH) trong 20,00 mL A → nhân hệ số pha loãng 100,0/20,00 = 5: n(tổng) = 4,8645 mmol → khối lượng tinh khiết = 4,8645·10<sup>−3</sup>·122,12 = 0,5941 g → % = 0,5941/0,8500·100 = 69,89 %. Lỗi hay gặp: «13,98 %» (quên hệ số pha loãng 5 lần, dùng luôn n trong 20,00 mL A làm n(tổng)); «2,80 %» (dùng ngược hệ số pha loãng, nhân với 20,00/100,0 thay vì 100,0/20,00); «82,47 %» (nhầm dùng khối lượng mol của muối natri benzoat C<sub>6</sub>H<sub>5</sub>COONa (144,11) — muối tạo thành trong phản ứng — thay vì M = 122,12 của acid benzoic)." },
  { id: "CD-B025", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 4, de: "Với dữ kiện của phép chuẩn độ acid benzoic ở trên (0,8500 g mẫu định mức 100,0 mL, hút 20,00 mL chuẩn bằng NaOH 0,1035 M hết 9,40 mL), tính pH gần đúng tại điểm tương đương của phép chuẩn độ 20,00 mL này (pK<sub>a</sub> acid benzoic = 4,19).", phuongAn: ["2,84", "8,35", "5,65", "8,44"], dapAn: "B", loiGiai: "Tổng thể tích tại tương đương = 20,00 + 9,40 = 29,40 mL; n(C<sub>6</sub>H<sub>5</sub>COO<sup>−</sup>) = n(NaOH) = 0,9729·10<sup>−3</sup> mol → C = 0,03309 M. K<sub>b</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>−9,81</sup>; [OH<sup>−</sup>] = √(K<sub>b</sub>C) = 2,26·10<sup>−6</sup> M → pOH = 5,65 → pH = 8,35. Lỗi hay gặp: «8,44» (quên cộng thể tích NaOH đã thêm vào mẫu số, chỉ dùng 20,00 mL); «5,65» (tính đúng pOH nhưng báo nhầm là pH, quên đổi pOH → pH); «2,84» (nhầm dùng trực tiếp K<sub>a</sub> của C<sub>6</sub>H<sub>5</sub>COOH để tính [H<sup>+</sup>] = √(K<sub>a</sub>C), coi sai bản chất C<sub>6</sub>H<sub>5</sub>COO<sup>−</sup> là một acid)." },
  { id: "CD-B026", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 4, de: "Chuẩn hóa NaOH: hút 10,00 mL dung dịch NaOH cần chuẩn hóa, chuẩn độ bằng dung dịch KHP chuẩn gốc 0,1006 M (phản ứng 1 : 1), hết 10,45 mL. Dùng đúng dung dịch NaOH này chuẩn độ 10,00 mL giấm ăn đậm đặc đã pha loãng 10 lần (dung dịch B), hết 12,60 mL, chỉ thị phenolphtalein. Tính nồng độ CH<sub>3</sub>COOH trong giấm ăn gốc.", phuongAn: ["0,1325 M", "1,213 M", "1,26 M", "1,325 M"], dapAn: "D", loiGiai: "C(NaOH) = 0,1006·10,45/10,00 = 0,10513 M. n(CH<sub>3</sub>COOH) trong 10,00 mL B = 0,10513·12,60 = 1,3246 mmol → C<sub>B</sub> = 0,13246 M → C<sub>gốc</sub> = C<sub>B</sub>·10 = 1,325 M. Lỗi hay gặp: «1,26 M» (bỏ qua bước chuẩn hóa, dùng luôn nồng độ danh nghĩa 0,1000 M của NaOH); «0,1325 M» (quên hệ số pha loãng 10 lần cuối cùng, báo nồng độ của B); «1,213 M» (đảo ngược tỉ số thể tích khi chuẩn hóa NaOH, tính C(NaOH) = 0,1006·10,00/10,45)." },
  { id: "CD-B027", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 4, de: "Cân 10,4520 g mẫu nước lau kính đậm đặc và 40,3180 g nước cất, trộn đều thành 50,7700 g dung dịch A. Cân 4,205 g dung dịch A, chuẩn độ bằng HCl 0,1050 M với chỉ thị bromocresol lục, hết 13,40 mL. Tính % NH<sub>3</sub> (khối lượng, M = 17,03) trong mẫu nước lau kính ban đầu.", phuongAn: ["0,117 %", "2,77 %", "0,570 %", "5,93 %"], dapAn: "B", loiGiai: "n(HCl) = 0,1050·13,40 = 1,407 mmol = n(NH<sub>3</sub>) trong 4,205 g A → khối lượng NH<sub>3</sub> = 1,407·10<sup>−3</sup>·17,03 = 0,02396 g → %NH<sub>3</sub> trong A = 0,02396/4,205·100 = 0,570 %. Vì A gồm mẫu gốc + nước theo khối lượng, %NH<sub>3</sub> trong mẫu gốc = 0,570 %·(50,7700/10,4520) = 2,77 %. Lỗi hay gặp: «0,570 %» (quên nhân hệ số pha loãng theo khối lượng, báo luôn %NH<sub>3</sub> trong dung dịch A); «0,117 %» (dùng ngược hệ số pha loãng khối lượng, nhân với 10,4520/50,7700); «5,93 %» (nhầm dùng M = 36,46 của HCl thay vì M = 17,03 của NH<sub>3</sub>)." },
  { id: "CD-B028", chuong: "chuan-do-axit-bazo", dang: "D06 · Định lượng mẫu thật", dangMoi: true, mucDo: 2, de: "Cân 0,4800 g mẫu tinh thể thương phẩm chứa acid benzoic (M = 122,12), hòa tan hoàn toàn trong nước ấm, chuẩn độ bằng NaOH 0,1000 M, hết 29,80 mL. Biết chuẩn độ mẫu trắng (chỉ nước cất, không có mẫu) cũng tiêu tốn 1,80 mL dung dịch NaOH này do CO<sub>2</sub> hòa tan trong nước. Tính % độ tinh khiết acid benzoic trong mẫu (đã trừ mẫu trắng).", phuongAn: ["71,24 %", "84,06 %", "66,66 %", "75,82 %"], dapAn: "A", loiGiai: "Thể tích NaOH thực phản ứng với acid benzoic = 29,80 − 1,80 = 28,00 mL → n(NaOH) = 0,1000·28,00 = 2,800 mmol = n(C<sub>6</sub>H<sub>5</sub>COOH) → khối lượng tinh khiết = 2,800·10<sup>−3</sup>·122,12 = 0,3419 g → % = 0,3419/0,4800·100 = 71,24 %. Lỗi hay gặp: «75,82 %» (quên trừ mẫu trắng, dùng nguyên 29,80 mL); «84,06 %» (nhầm dùng khối lượng mol của muối natri benzoat 144,11 thay vì acid benzoic 122,12); «66,66 %» (trừ mẫu trắng hai lần, dùng 29,80 − 2·1,80 = 26,20 mL)." },
  { id: "CD-B029", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 3, de: "Cất NH<sub>3</sub> từ 10,00 mL mẫu nước mắm, hấp thụ vào 20,00 mL dung dịch H<sub>2</sub>SO<sub>4</sub> 0,1000 M (dư, phản ứng 2NH<sub>3</sub> + H<sub>2</sub>SO<sub>4</sub> → (NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>). Chuẩn độ acid dư bằng NaOH 0,1000 M (H<sub>2</sub>SO<sub>4</sub> + 2NaOH → Na<sub>2</sub>SO<sub>4</sub> + 2H<sub>2</sub>O), hết 14,00 mL. Tính hàm lượng N trong mẫu theo g N/L.", phuongAn: ["3,64 g/L", "5,60 g/L", "1,82 g/L", "1,68 g/L"], dapAn: "A", loiGiai: "n(H<sub>2</sub>SO<sub>4</sub>) ban đầu = 0,1000·20,00 = 2,000 mmol. n(NaOH) = 0,1000·14,00 = 1,400 mmol → n(H<sub>2</sub>SO<sub>4</sub>) dư = 1,400/2 = 0,700 mmol → n(H<sub>2</sub>SO<sub>4</sub>) phản ứng với NH<sub>3</sub> = 2,000 − 0,700 = 1,300 mmol → n(NH<sub>3</sub>) = 2·1,300 = 2,600 mmol. Khối lượng N = 2,600·10<sup>−3</sup>·14,01 = 0,03643 g → g N/L = 0,03643/(10,00·10<sup>−3</sup>) = 3,64 g/L. Lỗi hay gặp: «1,82 g/L» (quên hệ số 2 trong phản ứng 2NH<sub>3</sub> + H<sub>2</sub>SO<sub>4</sub>, coi n(NH<sub>3</sub>) = n(H<sub>2</sub>SO<sub>4</sub>) phản ứng); «1,68 g/L» (quên hệ số 2 khi tính lượng H<sub>2</sub>SO<sub>4</sub> dư từ NaOH, coi n(H<sub>2</sub>SO<sub>4</sub>) dư = n(NaOH)); «5,60 g/L» (quên hẳn bước chuẩn độ ngược, coi toàn bộ H<sub>2</sub>SO<sub>4</sub> ban đầu đã phản ứng hết với NH<sub>3</sub>)." },
  { id: "CD-B030", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 3, de: "Vô cơ hóa 1,000 g mẫu thức ăn chăn nuôi, cất NH<sub>3</sub> hấp thụ vào 24,50 mL dung dịch H<sub>2</sub>SO<sub>4</sub> 0,1000 M (dư). Chuẩn độ acid dư bằng NaOH 0,1000 M, hết 20,30 mL. Tính %N (khối lượng) trong mẫu.", phuongAn: ["6,86 %", "1,18 %", "4,02 %", "2,01 %"], dapAn: "C", loiGiai: "n(H<sub>2</sub>SO<sub>4</sub>) ban đầu = 0,1000·24,50 = 2,450 mmol. n(NaOH) = 0,1000·20,30 = 2,030 mmol → n(H<sub>2</sub>SO<sub>4</sub>) dư = 2,030/2 = 1,015 mmol → n(H<sub>2</sub>SO<sub>4</sub>) phản ứng = 2,450 − 1,015 = 1,435 mmol → n(NH<sub>3</sub>) = 2·1,435 = 2,870 mmol. Khối lượng N = 2,870·10<sup>−3</sup>·14,01 = 0,04021 g → %N = 0,04021/1,000·100 = 4,02 %. Lỗi hay gặp: «2,01 %» (quên hệ số 2 trong phản ứng NH<sub>3</sub> với H<sub>2</sub>SO<sub>4</sub>); «1,18 %» (quên hệ số 2 khi suy ra lượng H<sub>2</sub>SO<sub>4</sub> dư từ số mol NaOH); «6,86 %» (quên bước chuẩn độ ngược, coi toàn bộ H<sub>2</sub>SO<sub>4</sub> ban đầu đã hấp thụ hết NH<sub>3</sub>)." },
  { id: "CD-B031", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 4, de: "Hút 5,00 mL nước mắm, vô cơ hóa rồi định mức thành 100,0 mL (dung dịch A). Hút 10,00 mL A, định mức tiếp thành 50,00 mL (dung dịch A′, vì mẫu vẫn còn đậm đặc). Hút 20,00 mL A′, kiềm hóa và cất NH<sub>3</sub>, hấp thụ vào 20,00 mL H<sub>2</sub>SO<sub>4</sub> 0,0200 M (dư), chuẩn độ acid dư bằng NaOH 0,0200 M, hết 16,00 mL. Tính hàm lượng N trong nước mắm gốc theo g N/L.", phuongAn: ["33,62 g/L", "3,36 g/L", "16,81 g/L", "13,45 g/L"], dapAn: "A", loiGiai: "n(H<sub>2</sub>SO<sub>4</sub>) = 0,0200·20,00 = 0,400 mmol; n(NaOH) = 0,0200·16,00 = 0,320 mmol → dư = 0,160 mmol → phản ứng với NH<sub>3</sub> = 0,400 − 0,160 = 0,240 mmol → n(NH<sub>3</sub>) đo được (trong 20,00 mL A′) = 0,480 mmol. Hệ số pha loãng ngược: từ A′ về A là 50,00/20,00 = 2,5 lần, từ 10,00 mL A về A là 100,0/10,00 = 10 lần → tổng hệ số = 25. Số mol N trong 5,00 mL mẫu gốc = 0,480·25 = 12,00 mmol → khối lượng N = 12,00·10<sup>−3</sup>·14,01 = 0,16812 g → g N/L = 0,16812/(5,00·10<sup>−3</sup>) = 33,62 g/L. Lỗi hay gặp: «16,81 g/L» (quên hệ số 2 trong phản ứng NH<sub>3</sub> với H<sub>2</sub>SO<sub>4</sub>, chỉ bằng nửa kết quả đúng); «13,45 g/L» (chỉ nhân hệ số pha loãng của lần định mức đầu (10 lần), quên nhân tiếp hệ số 2,5 lần của lần định mức thứ hai); «3,36 g/L» (chỉ nhân hệ số pha loãng của lần định mức thứ hai (2,5 lần), quên nhân hệ số 10 lần của lần định mức đầu)." },
  { id: "CD-B032", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 4, de: "Cân 2,000 g mẫu bột cá, vô cơ hóa rồi định mức thành 100,0 mL (dung dịch A). Hút 10,00 mL A, định mức tiếp thành 40,00 mL (dung dịch A′). Hút 10,00 mL A′, cất NH<sub>3</sub>, hấp thụ vào 25,00 mL H<sub>2</sub>SO<sub>4</sub> 0,0250 M (dư), chuẩn độ acid dư bằng NaOH 0,0250 M, hết 37,15 mL. Tính %N (khối lượng) trong mẫu bột cá.", phuongAn: ["4,50 %", "9,00 %", "2,25 %", "0,90 %"], dapAn: "B", loiGiai: "n(H<sub>2</sub>SO<sub>4</sub>) = 0,0250·25,00 = 0,625 mmol; n(NaOH) = 0,0250·37,15 = 0,92875 mmol → dư = 0,464375 mmol → phản ứng với NH<sub>3</sub> = 0,625 − 0,464375 = 0,160625 mmol → n(NH<sub>3</sub>) đo được = 0,32125 mmol. Hệ số pha loãng: 100,0/10,00 = 10 và 40,00/10,00 = 4 → tổng 40. Số mol N trong mẫu = 0,32125·40 = 12,85 mmol → khối lượng N = 12,85·10<sup>−3</sup>·14,01 = 0,18003 g → %N = 0,18003/2,000·100 = 9,00 %. Lỗi hay gặp: «4,50 %» (quên hệ số 2 trong phản ứng NH<sub>3</sub> với H<sub>2</sub>SO<sub>4</sub>, chỉ bằng nửa kết quả đúng); «2,25 %» (chỉ nhân hệ số pha loãng của lần định mức đầu (10 lần), quên nhân tiếp hệ số 4 lần); «0,90 %» (chỉ nhân hệ số pha loãng của lần định mức thứ hai (4 lần), quên nhân hệ số 10 lần của lần định mức đầu)." },
  { id: "CD-B033", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 2, de: "Hấp thụ NH<sub>3</sub> cất được từ một mẫu vào 25,00 mL dung dịch H<sub>2</sub>SO<sub>4</sub> 0,1000 M (dư). Chuẩn độ lượng acid dư bằng NaOH 0,1000 M, hết 9,50 mL, chỉ thị metyl đỏ. Tính số mmol NH<sub>3</sub> đã hấp thụ.", phuongAn: ["3,10 mmol", "5,00 mmol", "2,025 mmol", "4,05 mmol"], dapAn: "D", loiGiai: "n(H<sub>2</sub>SO<sub>4</sub>) ban đầu = 0,1000·25,00 = 2,500 mmol; n(NaOH) = 0,1000·9,50 = 0,950 mmol → n(H<sub>2</sub>SO<sub>4</sub>) dư = 0,950/2 = 0,475 mmol → n(H<sub>2</sub>SO<sub>4</sub>) phản ứng = 2,500 − 0,475 = 2,025 mmol → n(NH<sub>3</sub>) = 2·2,025 = 4,05 mmol. Lỗi hay gặp: «2,025 mmol» (quên hệ số 2 trong phản ứng 2NH<sub>3</sub> + H<sub>2</sub>SO<sub>4</sub>, dừng lại ở số mol H<sub>2</sub>SO<sub>4</sub> đã phản ứng); «3,10 mmol» (quên hệ số 2 khi suy n(H<sub>2</sub>SO<sub>4</sub>) dư từ n(NaOH), coi hai chất phản ứng 1 : 1); «5,00 mmol» (quên bước chuẩn độ ngược, nhân đôi toàn bộ lượng H<sub>2</sub>SO<sub>4</sub> ban đầu)." },
  { id: "CD-B034", chuong: "chuan-do-axit-bazo", dang: "D07 · Kjeldahl và chuẩn độ ngược", dangMoi: true, mucDo: 3, de: "Trong phép chuẩn độ ngược Kjeldahl, lượng H<sub>2</sub>SO<sub>4</sub> hấp thụ dư được chuẩn độ bằng NaOH với chỉ thị metyl đỏ (khoảng đổi màu 4,4 – 6,2; đỏ ở pH thấp, vàng ở pH cao). Khi nhỏ NaOH đến điểm cuối, màu của dung dịch chuyển theo chiều nào?", phuongAn: ["Vàng → đỏ", "Hồng → không màu", "Không đổi màu vì môi trường luôn acid", "Đỏ → vàng"], dapAn: "D", loiGiai: "Trước điểm cuối dung dịch còn dư nhiều H<sub>2</sub>SO<sub>4</sub>, pH thấp nên metyl đỏ có màu đỏ; khi nhỏ NaOH đến hết acid dư, pH tăng dần qua khoảng 4,4 – 6,2 nên chỉ thị chuyển sang vàng. Lỗi hay gặp: «Vàng → đỏ» (đảo ngược chiều đổi màu, quên rằng ở đây pH đang tăng dần khi thêm NaOH); «Không đổi màu vì môi trường luôn acid» (quên rằng chuẩn độ ngược bằng NaOH làm pH tăng dần đến khi hết acid dư); «Hồng → không màu» (nhầm sang chỉ thị phenolphtalein, không phải metyl đỏ như đề cho)." },
  { id: "CD-B035", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 2, de: "Tính nồng độ CH<sub>3</sub>COOH trong dung dịch B.", phuongAn: ["0,04845 M", "0,0850 M", "0,570 M", "0,969 M"], dapAn: "A", loiGiai: "n(NaOH) = 0,0850·11,40 = 0,969 mmol = n(CH<sub>3</sub>COOH) (1 : 1) trong 20,00 mL B → C<sub>B</sub> = 0,969/20,00 = 0,04845 M. Lỗi hay gặp: «0,0850 M» (nhầm lẫn, lấy luôn nồng độ NaOH đã cho làm đáp số mà không tính toán); «0,969 M» (quên chia cho thể tích mẫu, báo luôn số mmol NaOH đã dùng làm nồng độ); «0,570 M» (quên nhân với nồng độ NaOH, chỉ lấy tỉ số thể tích V(NaOH)/V(mẫu) = 11,40/20,00).", chum: "CD-C01", dan: "Xác định hàm lượng acid acetic trong giấm ăn: hút 20,00 mL giấm (dung dịch A) cho vào bình định mức 200,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm 2–3 giọt phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0850 M đến khi xuất hiện màu hồng nhạt bền trong 30 giây, hết 11,40 mL NaOH." },
  { id: "CD-B036", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Từ đó suy ra nồng độ CH<sub>3</sub>COOH trong giấm ăn ban đầu (dung dịch A).", phuongAn: ["0,004845 M", "4,85 M", "0,04845 M", "0,4845 M"], dapAn: "D", loiGiai: "B pha loãng 200,0/20,00 = 10 lần từ A nên C<sub>A</sub> = C<sub>B</sub>·10 = 0,04845·10 = 0,4845 M. Lỗi hay gặp: «0,04845 M» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,004845 M» (dùng ngược hệ số pha loãng 20,00/200,0); «4,85 M» (nhân hệ số pha loãng hai lần, tưởng cả bước định mức A→B lẫn bước hút B đem chuẩn độ đều là pha loãng).", chum: "CD-C01", dan: "Xác định hàm lượng acid acetic trong giấm ăn: hút 20,00 mL giấm (dung dịch A) cho vào bình định mức 200,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm 2–3 giọt phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0850 M đến khi xuất hiện màu hồng nhạt bền trong 30 giây, hết 11,40 mL NaOH." },
  { id: "CD-B037", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Tính pH của dung dịch B tại điểm tương đương của phép chuẩn độ trên (pK<sub>a</sub> CH<sub>3</sub>COOH = 4,75).", phuongAn: ["5,38", "8,62", "8,72", "3,13"], dapAn: "B", loiGiai: "Tổng thể tích tại tương đương = 20,00 + 11,40 = 31,40 mL; C(CH<sub>3</sub>COO<sup>−</sup>) = 0,969/31,40 = 0,03086 M. K<sub>b</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>−9,25</sup>; [OH<sup>−</sup>] = √(K<sub>b</sub>C) = 4,17·10<sup>−6</sup> M → pOH = 5,38 → pH = 8,62. Lỗi hay gặp: «8,72» (quên cộng thể tích NaOH đã thêm vào mẫu số, dùng nhầm 20,00 mL); «3,13» (nhầm dùng K<sub>a</sub> thay vì K<sub>b</sub> để tính [H<sup>+</sup>] = √(K<sub>a</sub>C)); «5,38» (tính đúng pOH nhưng báo nhầm là pH, quên đổi pOH → pH).", chum: "CD-C01", dan: "Xác định hàm lượng acid acetic trong giấm ăn: hút 20,00 mL giấm (dung dịch A) cho vào bình định mức 200,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm 2–3 giọt phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0850 M đến khi xuất hiện màu hồng nhạt bền trong 30 giây, hết 11,40 mL NaOH." },
  { id: "CD-B038", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 4, de: "Từ nồng độ CH<sub>3</sub>COOH trong A, tính % khối lượng CH<sub>3</sub>COOH trong giấm ăn (khối lượng riêng d = 1,010 g/mL, M = 60,05).", phuongAn: ["2,11 %", "2,88 %", "2,77 %", "0,288 %"], dapAn: "B", loiGiai: "%m = C<sub>A</sub>·M/(d·1000)·100 = 0,4845·60,05/(1,010·1000)·100 = 2,88 %. Lỗi hay gặp: «0,288 %» (quên hệ số pha loãng 10 lần, dùng C<sub>B</sub> thay vì C<sub>A</sub>); «2,11 %» (tính sai khối lượng mol, đếm thiếu một nguyên tử O trong công thức nên dùng M = 44,05 thay vì 60,05); «2,77 %» (nhớ nhầm khối lượng riêng giấm là 1,05 g/mL thay vì d = 1,010 g/mL đề cho).", chum: "CD-C01", dan: "Xác định hàm lượng acid acetic trong giấm ăn: hút 20,00 mL giấm (dung dịch A) cho vào bình định mức 200,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm 2–3 giọt phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0850 M đến khi xuất hiện màu hồng nhạt bền trong 30 giây, hết 11,40 mL NaOH." },
  { id: "CD-B039", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 2, de: "Tính nồng độ NH<sub>3</sub> trong dung dịch B.", phuongAn: ["2,079 M", "0,04158 M", "0,1050 M", "0,396 M"], dapAn: "B", loiGiai: "n(HCl) = 0,1050·19,80 = 2,079 mmol = n(NH<sub>3</sub>) (1 : 1) trong 50,00 mL B → C<sub>B</sub> = 2,079/50,00 = 0,04158 M. Lỗi hay gặp: «0,1050 M» (nhầm lẫn, lấy luôn nồng độ HCl đã cho làm đáp số mà không tính toán); «2,079 M» (quên chia cho thể tích mẫu, báo luôn số mmol HCl đã dùng làm nồng độ); «0,396 M» (quên nhân với nồng độ HCl, chỉ lấy tỉ số thể tích V(HCl)/V(mẫu) = 19,80/50,00).", chum: "CD-C02", dan: "Xác định hàm lượng NH<sub>3</sub> trong nước lau kính: hút 25,00 mL mẫu (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 50,00 mL dung dịch B, chuẩn độ bằng dung dịch HCl 0,1050 M với chỉ thị bromocresol lục (chuyển từ xanh lam sang vàng), hết 19,80 mL." },
  { id: "CD-B040", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Từ đó suy ra nồng độ NH<sub>3</sub> trong mẫu nước lau kính ban đầu (dung dịch A).", phuongAn: ["0,04158 M", "0,4158 M", "0,004158 M", "4,16 M"], dapAn: "B", loiGiai: "B pha loãng 250,0/25,00 = 10 lần từ A nên C<sub>A</sub> = C<sub>B</sub>·10 = 0,04158·10 = 0,4158 M. Lỗi hay gặp: «0,04158 M» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,004158 M» (dùng ngược hệ số pha loãng 25,00/250,0); «4,16 M» (nhân hệ số pha loãng hai lần, tưởng cả bước định mức A→B lẫn bước hút B đem chuẩn độ đều là pha loãng).", chum: "CD-C02", dan: "Xác định hàm lượng NH<sub>3</sub> trong nước lau kính: hút 25,00 mL mẫu (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 50,00 mL dung dịch B, chuẩn độ bằng dung dịch HCl 0,1050 M với chỉ thị bromocresol lục (chuyển từ xanh lam sang vàng), hết 19,80 mL." },
  { id: "CD-B041", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Tính pH của dung dịch B tại điểm tương đương của phép chuẩn độ trên (pK<sub>b</sub> NH<sub>3</sub> = 4,75).", phuongAn: ["5,39", "10,78", "3,14", "5,32"], dapAn: "A", loiGiai: "Tổng thể tích tại tương đương = 50,00 + 19,80 = 69,80 mL; C(NH<sub>4</sub><sup>+</sup>) = 2,079/69,80 = 0,02979 M. K<sub>a</sub> = 10<sup>−9,25</sup>; [H<sup>+</sup>] = √(K<sub>a</sub>C) = 4,09·10<sup>−6</sup> M → pH = 5,39. Lỗi hay gặp: «5,32» (quên cộng thể tích HCl đã thêm vào mẫu số, dùng nhầm 50,00 mL); «3,14» (nhầm dùng trực tiếp K<sub>b</sub> = 10<sup>−4,75</sup> của NH<sub>3</sub> làm K<sub>a</sub> của NH<sub>4</sub><sup>+</sup>); «10,78» (quên khai căn bậc hai, tính pH = pK<sub>a</sub> − lgC thay vì ½(pK<sub>a</sub> − lgC)).", chum: "CD-C02", dan: "Xác định hàm lượng NH<sub>3</sub> trong nước lau kính: hút 25,00 mL mẫu (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 50,00 mL dung dịch B, chuẩn độ bằng dung dịch HCl 0,1050 M với chỉ thị bromocresol lục (chuyển từ xanh lam sang vàng), hết 19,80 mL." },
  { id: "CD-B042", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 4, de: "Từ nồng độ NH<sub>3</sub> trong A, tính hàm lượng NH<sub>3</sub> (M = 17,03) trong mẫu ban đầu theo g/L.", phuongAn: ["5,83 g/L", "0,708 g/L", "15,16 g/L", "7,08 g/L"], dapAn: "D", loiGiai: "g/L = C<sub>A</sub>·M = 0,4158·17,03 = 7,08 g/L. Lỗi hay gặp: «0,708 g/L» (quên hệ số pha loãng 10 lần, dùng C<sub>B</sub> thay vì C<sub>A</sub>); «5,83 g/L» (nhầm dùng M = 14,01 của nguyên tố N thay vì M = 17,03 của phân tử NH<sub>3</sub>); «15,16 g/L» (nhầm dùng M = 36,46 của HCl — chất chuẩn dùng để định lượng — thay vì M = 17,03 của NH<sub>3</sub>).", chum: "CD-C02", dan: "Xác định hàm lượng NH<sub>3</sub> trong nước lau kính: hút 25,00 mL mẫu (dung dịch A) cho vào bình định mức 250,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 50,00 mL dung dịch B, chuẩn độ bằng dung dịch HCl 0,1050 M với chỉ thị bromocresol lục (chuyển từ xanh lam sang vàng), hết 19,80 mL." },
  { id: "CD-B043", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 2, de: "Tính nồng độ acid citric (C<sub>3</sub>H<sub>4</sub>(OH)(COOH)<sub>3</sub>, pK<sub>a1,2,3</sub> = 3,128 ; 4,761 ; 6,396) trong dung dịch B.", phuongAn: ["0,0189 M", "0,0378 M", "0,0126 M", "0,252 M"], dapAn: "C", loiGiai: "n(NaOH) = 0,0900·8,40 = 0,756 mmol; vì tỉ lệ 1 acid citric : 3 NaOH nên n(acid citric) = 0,756/3 = 0,252 mmol trong 20,00 mL B → C<sub>B</sub> = 0,252/20,00 = 0,0126 M. Lỗi hay gặp: «0,0378 M» (quên hệ số 3, coi phản ứng 1 : 1); «0,0189 M» (chia nhầm cho 2 thay vì 3); «0,252 M» (quên chia cho thể tích mẫu, báo luôn số mmol acid citric làm nồng độ).", chum: "CD-C03", dan: "Xác định hàm lượng acid citric trong nước cam: hút 20,00 mL nước cam (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0900 M đến hồng nhạt bền, hết 8,40 mL (phản ứng theo tỉ lệ 1 acid citric : 3 NaOH)." },
  { id: "CD-B044", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Từ đó suy ra nồng độ acid citric trong nước cam ban đầu (dung dịch A).", phuongAn: ["0,00252 M", "0,0630 M", "0,315 M", "0,0126 M"], dapAn: "B", loiGiai: "B pha loãng 100,0/20,00 = 5 lần từ A nên C<sub>A</sub> = C<sub>B</sub>·5 = 0,0126·5 = 0,0630 M. Lỗi hay gặp: «0,0126 M» (quên hệ số pha loãng 5 lần, báo luôn nồng độ của B); «0,00252 M» (dùng ngược hệ số pha loãng 20,00/100,0); «0,315 M» (nhân hệ số pha loãng hai lần, tưởng cả bước định mức A→B lẫn bước hút B đem chuẩn độ đều là pha loãng).", chum: "CD-C03", dan: "Xác định hàm lượng acid citric trong nước cam: hút 20,00 mL nước cam (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0900 M đến hồng nhạt bền, hết 8,40 mL (phản ứng theo tỉ lệ 1 acid citric : 3 NaOH)." },
  { id: "CD-B045", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Dạng tồn tại chiếm ưu thế của acid citric trong dung dịch B ngay tại thời điểm phenolphtalein đổi màu (pH 8,2 – 10,0) là", phuongAn: ["HCit<sup>2−</sup>", "H<sub>2</sub>Cit<sup>−</sup>", "Cit<sup>3−</sup>", "C<sub>3</sub>H<sub>4</sub>(OH)(COOH)<sub>3</sub> (H<sub>3</sub>Cit)"], dapAn: "C", loiGiai: "Cả ba pK<sub>a</sub> (3,128 ; 4,761 ; 6,396) đều nhỏ hơn nhiều so với pH 8,2 – 10,0 nên cả ba proton acid đã bị trung hòa hoàn toàn: dạng chiếm ưu thế là Cit<sup>3−</sup>. Lỗi hay gặp: chọn «H<sub>3</sub>Cit» (nhầm với dạng ban đầu, chưa phản ứng); chọn «H<sub>2</sub>Cit<sup>−</sup>» (chỉ tính mất 1 proton); chọn «HCit<sup>2−</sup>» (chỉ tính mất 2 proton, quên pH tại điểm dừng còn cao hơn cả pK<sub>a3</sub>).", chum: "CD-C03", dan: "Xác định hàm lượng acid citric trong nước cam: hút 20,00 mL nước cam (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0900 M đến hồng nhạt bền, hết 8,40 mL (phản ứng theo tỉ lệ 1 acid citric : 3 NaOH)." },
  { id: "CD-B046", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 4, de: "Từ nồng độ acid citric trong A, tính hàm lượng acid citric (M = 192,124) trong nước cam ban đầu theo g/L.", phuongAn: ["12,10 g/L", "36,31 g/L", "2,42 g/L", "13,24 g/L"], dapAn: "A", loiGiai: "g/L = C<sub>A</sub>·M = 0,0630·192,124 = 12,10 g/L. Lỗi hay gặp: «2,42 g/L» (quên hệ số pha loãng 5 lần, dùng C<sub>B</sub> thay vì C<sub>A</sub>); «13,24 g/L» (nhầm dùng khối lượng mol của acid citric ngậm một nước, M = 210,14, thay vì dạng khan M = 192,124); «36,31 g/L» (quên hệ số 3 trong tỉ lệ phản ứng ngay từ bước tính mol, dù vẫn nhân đúng hệ số pha loãng 5 lần).", chum: "CD-C03", dan: "Xác định hàm lượng acid citric trong nước cam: hút 20,00 mL nước cam (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 20,00 mL dung dịch B, thêm phenolphtalein, chuẩn độ bằng dung dịch NaOH 0,0900 M đến hồng nhạt bền, hết 8,40 mL (phản ứng theo tỉ lệ 1 acid citric : 3 NaOH)." },
  { id: "CD-B047", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 2, de: "Tính nồng độ HCOOH trong dung dịch B.", phuongAn: ["0,0410 M", "0,0500 M", "0,410 M", "0,820 M"], dapAn: "A", loiGiai: "n(NaOH) = 0,0500·8,20 = 0,410 mmol = n(HCOOH) (1 : 1) trong 10,00 mL B → C<sub>B</sub> = 0,410/10,00 = 0,0410 M. Lỗi hay gặp: «0,0500 M» (nhầm lẫn, lấy luôn nồng độ NaOH đã cho làm đáp số mà không tính toán); «0,410 M» (quên chia cho thể tích mẫu, báo luôn số mmol NaOH đã dùng làm nồng độ); «0,820 M» (quên nhân với nồng độ NaOH, chỉ lấy tỉ số thể tích V(NaOH)/V(mẫu) = 8,20/10,00).", chum: "CD-C04", dan: "Xác định hàm lượng acid formic (HCOOH) trong một dung dịch tẩy cặn: hút 10,00 mL mẫu (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng dung dịch NaOH 0,0500 M, hết 8,20 mL." },
  { id: "CD-B048", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Từ đó suy ra nồng độ HCOOH trong dung dịch tẩy cặn ban đầu (dung dịch A).", phuongAn: ["0,410 M", "0,0410 M", "4,10 M", "0,00410 M"], dapAn: "A", loiGiai: "B pha loãng 100,0/10,00 = 10 lần từ A nên C<sub>A</sub> = C<sub>B</sub>·10 = 0,0410·10 = 0,410 M. Lỗi hay gặp: «0,0410 M» (quên hệ số pha loãng 10 lần, báo luôn nồng độ của B); «0,00410 M» (dùng ngược hệ số pha loãng 10,00/100,0); «4,10 M» (nhân hệ số pha loãng hai lần, tưởng cả bước định mức A→B lẫn bước hút B đem chuẩn độ đều là pha loãng).", chum: "CD-C04", dan: "Xác định hàm lượng acid formic (HCOOH) trong một dung dịch tẩy cặn: hút 10,00 mL mẫu (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng dung dịch NaOH 0,0500 M, hết 8,20 mL." },
  { id: "CD-B049", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 3, de: "Tính pH của dung dịch B tại điểm tương đương của phép chuẩn độ trên (pK<sub>a</sub> HCOOH = 3,77).", phuongAn: ["5,94", "8,19", "2,71", "8,06"], dapAn: "D", loiGiai: "Tổng thể tích tại tương đương = 10,00 + 8,20 = 18,20 mL; C(HCOO<sup>−</sup>) = 0,410/18,20 = 0,02253 M. K<sub>b</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>−10,23</sup>; [OH<sup>−</sup>] = √(K<sub>b</sub>C) = 1,15·10<sup>−6</sup> M → pOH = 5,94 → pH = 8,06. Lỗi hay gặp: «8,19» (quên cộng thể tích NaOH đã thêm vào mẫu số, dùng nhầm 10,00 mL); «2,71» (nhầm dùng K<sub>a</sub> thay vì K<sub>b</sub> để tính [H<sup>+</sup>] = √(K<sub>a</sub>C)); «5,94» (tính đúng pOH nhưng báo nhầm là pH, quên đổi pOH → pH).", chum: "CD-C04", dan: "Xác định hàm lượng acid formic (HCOOH) trong một dung dịch tẩy cặn: hút 10,00 mL mẫu (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng dung dịch NaOH 0,0500 M, hết 8,20 mL." },
  { id: "CD-B050", chuong: "chuan-do-axit-bazo", dang: "D08 · Câu chùm quy trình chuẩn độ", dangMoi: true, mucDo: 4, de: "Chọn chỉ thị phù hợp nhất để nhận biết điểm tương đương của phép chuẩn độ trên.", phuongAn: ["Metyl da cam (3,1 – 4,4 ; đỏ → vàng)", "Alizarin vàng (10,1 – 12,0 ; vàng → cam đỏ)", "Cresol đỏ (7,2 – 8,8 ; vàng → đỏ)", "Bromcresol lục (3,8 – 5,4 ; vàng → xanh lam)"], dapAn: "C", loiGiai: "pH tại điểm tương đương vừa tính được là 8,06, nằm gọn trong khoảng đổi màu 7,2 – 8,8 của cresol đỏ (nấc 2), đổi màu vàng → đỏ khi pH tăng qua điểm này. Lỗi hay gặp: chọn «Metyl da cam» (khoảng 3,1 – 4,4 quá thấp, còn xa điểm tương đương); chọn «Alizarin vàng» (khoảng 10,1 – 12,0 quá cao so với pH 8,06); chọn «Bromcresol lục» (khoảng 3,8 – 5,4 hoàn toàn không chứa pH tương đương 8,06).", chum: "CD-C04", dan: "Xác định hàm lượng acid formic (HCOOH) trong một dung dịch tẩy cặn: hút 10,00 mL mẫu (dung dịch A) cho vào bình định mức 100,0 mL, thêm nước cất đến vạch (dung dịch B). Hút 10,00 mL dung dịch B, chuẩn độ bằng dung dịch NaOH 0,0500 M, hết 8,20 mL." }
);
